import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;
    static int n;
    static int[][] p_mat;
    static int[] popcnt_arr;
    static long[][] q_vals;
    static int[] id_map;
    static List<List<Integer>> groups;
    static Map<Pair, Integer> memo_map;
    static int[] group_sizes;

    static class Pair {
        int index;
        long state;

        Pair(int index, long state) {
            this.index = index;
            this.state = state;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Pair)) return false;
            Pair pair = (Pair) o;
            return index == pair.index && state == pair.state;
        }

        @Override
        public int hashCode() {
            return Objects.hash(index, state);
        }
    }

    static long fast_pow(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    static long add_modulo(long a, long b) {
        a += b;
        if (a >= MOD) a -= MOD;
        return a;
    }

    static long solve(int index, long state) {
        if (state == 0) return 0;
        if (index == n) return 1;
        Pair key = new Pair(index, state);
        if (memo_map.containsKey(key)) return memo_map.get(key);
        long total = 0;
        int subsetLimit = 1 << n;
        for (int subset = 1; subset < subsetLimit; subset++) {
            long new_state = 0;
            List<Integer> group = groups.get(index);
            for (int k = 0; k < group.size(); k++) {
                if ((state & (1L << k)) == 0) continue;
                int c = group.get(k);
                int nxt = subset - (subset & c);
                new_state |= q_vals[c][nxt];
            }
            long temp = ((long) pro_mat[index][subset] * solve(index + 1, new_state)) % MOD;
            total = add_modulo(total, temp);
        }
        memo_map.put(key, (int) total);
        return total;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine());
        p_mat = new int[n][n];

        int inv_100 = (int) fast_pow(100, MOD - 2, MOD);
        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().split(" ");
            for (int j = 0; j < n; j++) {
                p_mat[i][j] = Integer.parseInt(parts[j]);
                p_mat[i][j] = (int) ((long) p_mat[i][j] * inv_100 % MOD);
            }
        }

        int size = 1 << n;
        long[][] pro_mat = new long[n][size];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < size; j++) {
                pro_mat[i][j] = 1;
                for (int k = 0; k < n; k++) {
                    if (((j >> k) & 1) == 1) {
                        pro_mat[i][j] = (pro_mat[i][j] * p_mat[i][k]) % MOD;
                    } else {
                        pro_mat[i][j] = (pro_mat[i][j] * (MOD + 1 - p_mat[i][k])) % MOD;
                    }
                }
            }
        }

        popcnt_arr = new int[size];
        for (int i = 0; i < size; i++) {
            popcnt_arr[i] = Integer.bitCount(i);
        }

        groups = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            groups.add(new ArrayList<>());
        }

        id_map = new int[size];
        for (int i = 0; i < size; i++) {
            groups.get(popcnt_arr[i]).add(i);
        }

        for (int i = 0; i < size; i++) {
            int cnt = popcnt_arr[i];
            id_map[i] = groups.get(cnt).indexOf(i);
        }

        q_vals = new long[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                q_vals[i][j] = 0;
            }
        }

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < n; j++) {
                if (((i >> j) & 1) == 0) {
                    q_vals[i][1 << j] = 1L << id_map[i | (1 << j)];
                }
            }
            for (int j = 0; j < size; j++) {
                q_vals[i][j] = q_vals[i][j & -j] | q_vals[i][j ^ (j & -j)];
            }
        }

        memo_map = new HashMap<>();
        System.out.println(solve(0, 1));
    }
}
